inline const PgTheme* pg_find_theme(const char* name) {
    static const PgTheme* k[] = {
        &kdefault,
        &kmonokai,
        &kdracula,
        &ksolarized_dark,
        &ksolarized_light,
        &kgithub_dark,
        &kgruvbox_dark,
        &kgruvbox_light,
        &knord,
        &kone_dark,
        &kparaiso_dark,
        &kparaiso_light,
        &kmaterial,
        &ktango,
        &knative,
        &kvim,
        &kxcode,
        &kzenburn,
        &kfruity,
        &kmanni,
        &kcolorful,
        &kpastie,
        &krainbow_dash,
        &ktrac,
        &kfriendly,
        &klovelace,
        &kemacs,
        &kbw,
        &klightbulb,
        &knight_owl,
        &kvs,
        &kstaroffice,
    };
    for (const PgTheme* t : k)
        if (t->name && strcmp(t->name, name) == 0) return t;
    return nullptr;
}
